  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Compound 33, which contains a morpholine substituent and a fused heteroaromatic core, showed excellent CNS penetration in mice with a brain-to-plasma Kp of 11.4 and negligible P-gp efflux, directly supporting that the query's morpholine/triazine polar features can still allow meaningful brain access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PRE-084, a morpholine-containing compound, was rapidly distributed to the CNS in mice with a brain concentration of 773.6 ng/g at Tmax, demonstrating that morpholine-based polar molecules can achieve high brain exposure after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "18F-JNJ-64413739, a CF3-substituted pyridine/heteroaromatic PET ligand, showed high brain uptake and fast kinetics in rodents and non-human primates, supporting CNS access for the CF3-heteroaromatic motif present in the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Flucytosine, a small polar amino-heterocycle, reaches CSF concentrations approximately 75% of serum levels in humans, showing that polar amino-heteroaromatic molecules can have excellent CNS penetration despite physicochemical properties that would suggest poor passive diffusion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A CF3-oxadiazole carboxylic acid was shown by dynamic PET to cross the BBB in rats, albeit with relatively low uptake, providing direct evidence that the CF3-heteroaromatic substructure can penetrate the blood-brain barrier.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted pass: multiple high-transfer in vivo CNS penetration measurements in molecules sharing key query features (morpholine, CF3-heteroaromatic, amino-heterocycle) demonstrate meaningful brain access, overriding the uncertain low-passive-diffusion prior.",
